using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long w, h, k;
    cin >> w >> h >> k;

    long long ans = 0;
    for (long long i = 0; i < k; ++i) {
        ans += 2 * (w + h) - 4;
        w -= 2;
        h -= 2;
    }

    cout << ans;
    return 0;
}

